//! Cross-reference streams, object streams and hybrid files (Q5, M5).
//!
//! Four hand-built fixtures, all generated by `tests/fixtures/make_fixtures.py`:
//!
//! - `xref-stream.pdf` — cross-reference is a `/Type /XRef` stream; objects 1–3
//!   live inside `/ObjStm` 5, object 4 is a plain stream.
//! - `classic-twin.pdf` — the same object graph with a classic `xref` table.
//! - `hybrid-xref.pdf` — classic table for the plain objects plus `/XRefStm`
//!   pointing at a stream that hides objects 1–3.
//! - `xref-stream-prev.pdf` — an incremental update that replaces object 4 and
//!   adds a second xref stream whose `/Prev` reaches the first one.

use pdf2::{Document, Object, ObjectId};

const XREF_STREAM: &[u8] = include_bytes!("fixtures/xref-stream.pdf");
const XREF_STREAM_PREV: &[u8] = include_bytes!("fixtures/xref-stream-prev.pdf");
const CLASSIC_TWIN: &[u8] = include_bytes!("fixtures/classic-twin.pdf");
const HYBRID: &[u8] = include_bytes!("fixtures/hybrid-xref.pdf");

const CONTENT: &[u8] = b"BT /F1 24 Tf 72 700 Td (Hello, PDF 2.0) Tj ET";
const UPDATED_CONTENT: &[u8] = b"BT /F1 24 Tf 72 700 Td (Hello again) Tj ET";

fn open(bytes: &[u8]) -> Document {
    Document::open(bytes).expect("fixture opens")
}

#[test]
fn an_xref_stream_file_opens() {
    let document = open(XREF_STREAM);
    assert_eq!(document.version(), "2.0");
    assert_eq!(document.trailer().get(b"Size"), Some(&Object::Integer(7)));
    assert_eq!(
        document.trailer().get(b"Type"),
        Some(&Object::name("XRef")),
        "the newest section *is* the trailer in an xref-stream file"
    );
}

#[test]
fn objects_inside_an_object_stream_are_extracted() {
    let document = open(XREF_STREAM);
    let catalog = document.get_object_by_number(1).expect("catalog");
    assert_eq!(
        catalog.as_dict().and_then(|dict| dict.get(b"Type")),
        Some(&Object::name("Catalog"))
    );
    assert!(document.contains_object(1), "compressed objects are live");

    let pages = document.get_object_by_number(2).expect("pages");
    assert_eq!(
        pages.as_dict().and_then(|dict| dict.get(b"Count")),
        Some(&Object::Integer(1))
    );

    let page = document.get_object_by_number(3).expect("page");
    assert_eq!(
        page.as_dict().and_then(|dict| dict.get(b"Contents")),
        Some(&Object::reference(ObjectId::new(4, 0)))
    );

    // The catalog is reachable through /Root, which lives in the xref stream.
    assert_eq!(
        document.catalog().expect("catalog"),
        catalog,
        "graph is consistent"
    );
}

#[test]
fn plain_streams_in_an_xref_stream_file_still_decode() {
    let document = open(XREF_STREAM);
    assert_eq!(
        document
            .stream_data(ObjectId::new(4, 0))
            .expect("content stream"),
        CONTENT
    );
}

#[test]
fn the_object_graph_matches_the_classic_twin() {
    let streamed = open(XREF_STREAM);
    let classic = open(CLASSIC_TWIN);
    for number in 1..=4 {
        assert_eq!(
            streamed.get_object_by_number(number).expect("streamed"),
            classic.get_object_by_number(number).expect("classic"),
            "object {number} must read the same through both cross-reference forms"
        );
    }
    assert_eq!(
        streamed.catalog().expect("streamed catalog"),
        classic.catalog().expect("classic catalog")
    );
}

#[test]
fn a_hybrid_file_reads_objects_through_xref_stm() {
    let document = open(HYBRID);
    assert!(
        matches!(
            document.trailer().get(b"XRefStm"),
            Some(Object::Integer(offset)) if *offset > 0
        ),
        "the classic trailer names the hidden stream: {:?}",
        document.trailer().get(b"XRefStm")
    );
    let catalog = document.catalog().expect("catalog from /XRefStm");
    assert_eq!(
        catalog.as_dict().and_then(|dict| dict.get(b"Type")),
        Some(&Object::name("Catalog"))
    );
    assert!(document.get_object_by_number(2).is_ok());
    assert!(document.get_object_by_number(3).is_ok());
    assert_eq!(
        document
            .stream_data(ObjectId::new(4, 0))
            .expect("plain object from the classic table"),
        CONTENT
    );
}

#[test]
fn prev_reaches_an_earlier_xref_stream() {
    let document = open(XREF_STREAM_PREV);
    // Object 4 was repainted by the update, so the newest entry wins.
    assert_eq!(
        document
            .stream_data(ObjectId::new(4, 0))
            .expect("updated content"),
        UPDATED_CONTENT
    );
    // Objects 1–3 only exist behind /Prev, inside the first xref stream.
    let catalog = document.get_object_by_number(1).expect("catalog via /Prev");
    assert_eq!(
        catalog.as_dict().and_then(|dict| dict.get(b"Type")),
        Some(&Object::name("Catalog"))
    );
    assert!(document.get_object_by_number(2).is_ok());
    assert!(document.get_object_by_number(3).is_ok());
}

#[test]
fn compressed_objects_are_fetched_lazily_and_cached() {
    let document = open(XREF_STREAM);
    // Fetching an object by id and by number must agree.
    assert_eq!(
        document.get_object(ObjectId::new(2, 0)).expect("by id"),
        document.get_object_by_number(2).expect("by number")
    );
    // An object stream member asked for twice returns the cached value.
    assert_eq!(
        document.get_object_by_number(3).expect("first"),
        document.get_object_by_number(3).expect("second")
    );
}

#[test]
fn every_truncation_of_the_xref_stream_fixture_is_handled() {
    for end in 0..XREF_STREAM.len() {
        let _ = Document::open(&XREF_STREAM[..end]);
    }
    for end in 0..HYBRID.len() {
        let _ = Document::open(&HYBRID[..end]);
    }
    assert!(Document::open(XREF_STREAM).is_ok());
    assert!(Document::open(HYBRID).is_ok());
}

#[test]
fn damaged_cross_reference_streams_are_errors() {
    // Break the /W array: the reader must complain, not guess.
    let mut broken = XREF_STREAM.to_vec();
    let at = broken
        .windows(5)
        .position(|window| window == b"/W [1")
        .expect("/W in the fixture");
    broken[at..at + 5].copy_from_slice(b"/W [9");
    assert!(Document::open(broken).is_err());

    // Break /Index: the default subsection then claims more rows than the
    // stream holds, which must be an error rather than a panic.
    let mut broken = XREF_STREAM_PREV.to_vec();
    let at = broken
        .windows(7)
        .position(|window| window == b"/Index ")
        .expect("/Index in the fixture");
    broken[at..at + 7].copy_from_slice(b"/Indey ");
    assert!(Document::open(&broken[..]).is_err());
}

#[test]
fn a_free_entry_generation_above_the_u16_range_is_clamped() {
    // Some writers put 65536 in the free head's generation field; it is never
    // used for a lookup, so it is clamped rather than refused — the pattern the
    // corpus file `ContentStreamCycleType3insideType3.pdf` carries.
    let bytes = std::fs::read(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/xref-generation.pdf"
    ))
    .expect("read xref-generation.pdf");
    let document = pdf2::Document::open(bytes).expect("open");
    assert_eq!(document.pages().expect("pages").len(), 1);
}

#[test]
fn a_startxref_that_points_inside_the_table_is_repaired() {
    // The fixture's `startxref` is 19 bytes into the table; the reader falls back
    // to the nearest `xref` keyword before it, which is the corpus file's pattern.
    let bytes = std::fs::read(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/startxref-hint.pdf"
    ))
    .expect("read startxref-hint.pdf");
    let document = pdf2::Document::open(bytes).expect("open");
    assert_eq!(document.pages().expect("pages").len(), 1);
}
